/* main.c: STM32F411 trigger box (Nucleo-F411RE or a "Black Pill" F411CE), generated by Vantage for
 * @@PROJECT@@ · @@VARIANT@@.
 *
 * TIM2 and TIM5 are 32-bit timers counting the 100 MHz timer clock (10 ns). The GNSS PPS is captured in hardware on
 * TIM2_CH1; every trigger line is a timer channel in output-compare mode, so each edge is placed by the timer itself
 * on the tick, with no software jitter: the interrupt only programs the next edge, long before it is due. TIM5 is
 * started by TIM2's enable through the internal trigger (ITR0, RM0383 13.3.15), so both count the same clock edges;
 * the self-test prints the difference between the two counters read back to back (a fixed bus delay, not corrected).
 * The scheduling core (trigger_core.c) disciplines the schedule to the PPS; without PPS it runs on the crystal (free,
 * or holdover with the learned frequency).
 *
 * Self-test: hold @@SELFTEST_PIN@@ low at reset: line n then gives n + 1 pulses of 2 ms, 20 ms apart, every second.
 * Status: one line a second on USART1 TX (PA9, 115200 8N1); the LED is on when locked, blinks once a second while
 * free or locking and four times a second in holdover.
 *
 * Only trigger pulses come out of this board. It drives nothing else.
 */
#include <stdio.h>
#include <string.h>

#include "stm32f4xx.h"
#include "trigger_core.h"
#include "trigger_plan.h"

static tb_state_t st;
static volatile uint32_t hi;                    /* TIM2 overflows: the upper half of the 64-bit tick count */
static uint32_t late, ms_now;
static uint8_t waiting[TB_MAX_LINES];           /* the line's channel waits for the rise (1) or the fall (0) */
static const tb_plan_t *plan = &TB_PLAN;

static TIM_TypeDef *tim_of(uint32_t line) { return TB_LINE_TIMER[line] == 5 ? TIM5 : TIM2; }

static volatile uint32_t *ccr_of(uint32_t line)
{
    TIM_TypeDef *t = tim_of(line);
    switch (TB_LINE_CHANNEL[line]) {
    case 1: return &t->CCR1;
    case 2: return &t->CCR2;
    case 3: return &t->CCR3;
    default: return &t->CCR4;
    }
}

static void oc_mode(uint32_t line, uint32_t mode)   /* OCxM: 1 active on match, 2 inactive on match, 4/5 force */
{
    TIM_TypeDef *t = tim_of(line);
    uint32_t ch = TB_LINE_CHANNEL[line];
    volatile uint32_t *ccmr = ch <= 2 ? &t->CCMR1 : &t->CCMR2;
    uint32_t sh = (ch == 1 || ch == 3) ? 4 : 12;
    *ccmr = (*ccmr & ~(7u << sh)) | (mode << sh);
}

static int64_t now64(void)
{
    uint32_t h1, h2, c, sr;
    do {
        h1 = hi;
        c = TIM2->CNT;
        sr = TIM2->SR;
        h2 = hi;
    } while (h1 != h2);                           /* the overflow interrupt ran in between: read again */
    if ((sr & TIM_SR_UIF) && c < 0x80000000u)
        h1++;                                     /* an overflow not yet counted by the interrupt */
    return ((int64_t)h1 << 32) | c;
}

/* program the channel's next edge; an edge already in the past is forced at once and counted as late */
static void arm(uint32_t line)
{
    for (;;) {
        tb_line_state_t *l = &st.ln[line];
        int64_t when = waiting[line] ? l->rise : l->fall;
        *ccr_of(line) = (uint32_t)when;
        oc_mode(line, waiting[line] ? 1u : 2u);
        if ((int32_t)((uint32_t)when - (uint32_t)now64()) > 0)
            return;                               /* still ahead: the timer places it */
        late++;
        oc_mode(line, waiting[line] ? 5u : 4u);    /* force the level the edge would have set */
        tim_of(line)->SR = ~(TIM_SR_CC1IF << (TB_LINE_CHANNEL[line] - 1));   /* and drop a match it raced */
        if (waiting[line]) {
            tb_line_started(&st, line);
            waiting[line] = 0;
        } else {
            int64_t r, f;
            tb_line_ended(&st, line);
            tb_line_next(&st, line, &r, &f);
            waiting[line] = 1;
        }
    }
}

static void channel_event(uint32_t line)
{
    if (waiting[line]) {                          /* the rise went out: the fall is next */
        tb_line_started(&st, line);
        waiting[line] = 0;
    } else {                                      /* the fall went out: fetch the next pulse */
        int64_t r, f;
        tb_line_ended(&st, line);
        tb_line_next(&st, line, &r, &f);
        waiting[line] = 1;
    }
    arm(line);
}

static void service(TIM_TypeDef *t, uint32_t timer_no)
{
    uint32_t sr = t->SR, line;
    for (line = 0; line < plan->n_lines; line++) {
        uint32_t flag = TIM_SR_CC1IF << (TB_LINE_CHANNEL[line] - 1);
        if (TB_LINE_TIMER[line] == timer_no && (sr & flag)) {
            t->SR = ~flag;
            channel_event(line);
        }
    }
}

void TIM2_IRQHandler(void)
{
    uint32_t sr = TIM2->SR;
    if (sr & TIM_SR_CC1IF) {                      /* the PPS edge, captured by the timer itself */
        uint32_t c = TIM2->CCR1, h = hi, line;
        if ((sr & TIM_SR_UIF) && c < 0x80000000u)
            h++;
        if (tb_on_pps(&st, ((int64_t)h << 32) | c))
            for (line = 0; line < plan->n_lines; line++)
                if (waiting[line]) {              /* the schedule stepped: refetch the rises not yet out */
                    int64_t r, f;
                    tb_line_next(&st, line, &r, &f);
                    arm(line);
                }
    }
    if (sr & TIM_SR_UIF) {
        TIM2->SR = ~TIM_SR_UIF;
        hi++;
    }
    service(TIM2, 2);
}

void TIM5_IRQHandler(void) { service(TIM5, 5); }

void SysTick_Handler(void) { ms_now++; }

/* ------------------------------------------------------------------ set-up */
static void clocks(void)
{
    /* HSE (TB_HSE_MHZ, bypassed on the Nucleo: ST-LINK's 8 MHz MCO) -> PLL: VCO 400 MHz, SYSCLK 100 MHz,
     * APB1 50 MHz (its timers 100 MHz), APB2 100 MHz. RM0383 6.3. */
    RCC->CR |= (TB_HSE_BYPASS ? RCC_CR_HSEBYP : 0u);
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY)) {
    }
    RCC->APB1ENR |= RCC_APB1ENR_PWREN;
    PWR->CR |= PWR_CR_VOS;                        /* voltage scale 1 for 100 MHz */
    FLASH->ACR = FLASH_ACR_ICEN | FLASH_ACR_DCEN | FLASH_ACR_PRFTEN | FLASH_ACR_LATENCY_3WS;
    RCC->PLLCFGR = (TB_HSE_MHZ << RCC_PLLCFGR_PLLM_Pos) | (400u << RCC_PLLCFGR_PLLN_Pos) |
                   (1u << RCC_PLLCFGR_PLLP_Pos) /* /4 */ | RCC_PLLCFGR_PLLSRC_HSE | (8u << RCC_PLLCFGR_PLLQ_Pos);
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
    }
    RCC->CFGR = RCC_CFGR_HPRE_DIV1 | RCC_CFGR_PPRE1_DIV2 | RCC_CFGR_PPRE2_DIV1 | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
    }
    SystemCoreClock = 100000000u;
}

static void pin_af(GPIO_TypeDef *g, uint32_t pin, uint32_t af)
{
    g->MODER = (g->MODER & ~(3u << (2 * pin))) | (2u << (2 * pin));
    g->OSPEEDR |= 3u << (2 * pin);
    g->AFR[pin >> 3] = (g->AFR[pin >> 3] & ~(15u << (4 * (pin & 7)))) | (af << (4 * (pin & 7)));
}

static void pin_mode(GPIO_TypeDef *g, uint32_t pin, uint32_t mode, uint32_t pull)
{
    g->MODER = (g->MODER & ~(3u << (2 * pin))) | (mode << (2 * pin));
    g->PUPDR = (g->PUPDR & ~(3u << (2 * pin))) | (pull << (2 * pin));
}

static GPIO_TypeDef *port(char p) { return p == 'A' ? GPIOA : p == 'B' ? GPIOB : GPIOC; }

static void uart_init(void)
{
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;
    pin_af(GPIOA, 9, 7);                          /* USART1_TX, AF7 */
    USART1->BRR = 100000000u / 115200u;           /* APB2 at 100 MHz, oversampling by 16 */
    USART1->CR1 = USART_CR1_TE | USART_CR1_UE;
}

static void uart_puts(const char *s)
{
    while (*s) {
        while (!(USART1->SR & USART_SR_TXE)) {
        }
        USART1->DR = (uint8_t)*s++;
    }
}

static void timers(void)
{
    uint32_t line;
    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN | RCC_APB1ENR_TIM5EN;
    TIM2->PSC = 0;
    TIM2->ARR = 0xffffffffu;
    TIM5->PSC = 0;
    TIM5->ARR = 0xffffffffu;
    TIM2->EGR = TIM_EGR_UG;                       /* load the prescalers */
    TIM5->EGR = TIM_EGR_UG;
    TIM2->SR = 0;
    TIM5->SR = 0;
    TIM2->CNT = 0;
    TIM5->CNT = 0;
    /* PPS: TIM2_CH1 input capture on the rising edge, no prescaler, no filter */
    TIM2->CCMR1 = (TIM2->CCMR1 & ~0xffu) | TIM_CCMR1_CC1S_0;
    TIM2->CCER |= TIM_CCER_CC1E;
    /* the lines: output compare, forced inactive until their first edge, no preload (a CCR write acts at once) */
    for (line = 0; line < plan->n_lines; line++) {
        TIM_TypeDef *t = tim_of(line);
        uint32_t ch = TB_LINE_CHANNEL[line];
        oc_mode(line, 4u);
        t->CCER |= (TIM_CCER_CC1E | (TB_ACTIVE_LOW ? TIM_CCER_CC1P : 0u)) << (4 * (ch - 1));
        t->DIER |= TIM_DIER_CC1IE << (ch - 1);
    }
    TIM2->DIER |= TIM_DIER_CC1IE | TIM_DIER_UIE;
    /* TIM5 starts with TIM2: TIM2's enable is its trigger output, TIM5 in trigger mode on ITR0 */
    TIM2->CR2 = (TIM2->CR2 & ~TIM_CR2_MMS) | TIM_CR2_MMS_0;
    TIM5->SMCR = (TIM5->SMCR & ~(TIM_SMCR_TS | TIM_SMCR_SMS)) | TIM_SMCR_SMS_2 | TIM_SMCR_SMS_1;
    NVIC_SetPriority(TIM2_IRQn, 0);
    NVIC_SetPriority(TIM5_IRQn, 0);               /* the same priority: the two handlers never interleave */
    NVIC_EnableIRQ(TIM2_IRQn);
    NVIC_EnableIRQ(TIM5_IRQn);
}

static void pins(void)
{
    uint32_t line;
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIOBEN | RCC_AHB1ENR_GPIOCEN;
    pin_af(port(TB_PPS_PORT), TB_PPS_PIN, 1);     /* TIM2_CH1, AF1 */
    for (line = 0; line < plan->n_lines; line++)
        pin_af(port(TB_LINE_PORT[line]), TB_LINE_PIN[line], TB_LINE_TIMER[line] == 5 ? 2u : 1u);
    pin_mode(port(TB_SELFTEST_PORT), TB_SELFTEST_PIN, 0u, 1u);     /* input, pull-up */
    pin_mode(port(TB_LED_PORT), TB_LED_PIN, 1u, 0u);               /* output */
}

static void led(int on)
{
    GPIO_TypeDef *g = port(TB_LED_PORT);
    if (on ^ TB_LED_ACTIVE_LOW)
        g->BSRR = 1u << TB_LED_PIN;
    else
        g->BSRR = 1u << (TB_LED_PIN + 16);
}

int main(void)
{
    uint32_t line, next_status = 0, i;
    char buf[160];
    int32_t d5 = 0;

    clocks();
    SysTick_Config(100000u);                      /* 1 ms */
    pins();
    for (i = 0; i < 100000u; i++)                 /* the pull-up settles */
        __NOP();
    if (!(port(TB_SELFTEST_PORT)->IDR & (1u << TB_SELFTEST_PIN)))
        plan = &TB_PLAN_SELFTEST;
    uart_init();
    timers();
    tb_init(&st, plan, 0);
    for (line = 0; line < plan->n_lines; line++) {
        int64_t r, f;
        tb_line_next(&st, line, &r, &f);
        waiting[line] = 1;
    }
    __disable_irq();
    TIM2->CR1 |= TIM_CR1_CEN;                     /* TIM5 starts with it */
    for (line = 0; line < plan->n_lines; line++)
        arm(line);
    d5 = (int32_t)(TIM5->CNT - TIM2->CNT);
    __enable_irq();
    snprintf(buf, sizeof buf, "vantage trigger box: %s plan, %lu lines, TIM5-TIM2 read-back %ld ticks\r\n",
             plan == &TB_PLAN ? "normal" : "self-test", (unsigned long)plan->n_lines, (long)d5);
    uart_puts(buf);

    for (;;) {
        __disable_irq();
        tb_poll(&st, now64());
        __enable_irq();
        if ((int32_t)(ms_now - next_status) >= 0) {
            tb_state_t s;
            next_status = ms_now + 1000u;
            __disable_irq();
            memcpy(&s, &st, sizeof s);
            __enable_irq();
            snprintf(buf, sizeof buf, "%s pps=%lu missed=%lu steps=%lu outliers=%lu resid_ns=%ld ppb=%ld late=%lu\r\n",
                     tb_state_name(s.state), (unsigned long)s.pps, (unsigned long)s.missed, (unsigned long)s.steps,
                     (unsigned long)s.outliers, (long)(s.resid * 10), (long)tb_ppb(&s), (unsigned long)late);
            uart_puts(buf);
        }
        led(st.state == TB_LOCKED ? 1 : st.state == TB_HOLDOVER ? (ms_now / 125u) % 2u : (ms_now / 500u) % 2u);
    }
}
